import { catalogue } from './catalogue.js';
import { productArt } from './product-art.js';
import { extractListing, validateSourceUrl, safeStorageGet, safeStorageSet, encodeSharedList, decodeSharedList } from './importer.js';
import { money, escapeHTML as e, summarizeCart, cartItem, spokenSummary, parseIncludedLines, extractPackageClauses } from './model.js';

const icons={arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',back:'<path d="M19 12H5m6 6-6-6 6-6"/>',play:'<path d="m9 5 11 7-11 7z"/>',eye:'<path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7-10-7-10-7Z"/><circle cx="12" cy="12" r="3"/>',audio:'<path d="m11 4-6 5H2v6h3l6 5zM16 8a6 6 0 0 1 0 8m3-11a10 10 0 0 1 0 14"/>',check:'<path d="m5 12 4 4L19 6"/>',bag:'<path d="M4 7h16l1 14H3L4 7Z"/><path d="M8 8V6a4 4 0 0 1 8 0v2"/>',compare:'<path d="M5 5h14M5 12h14M5 19h14M9 2v20m6-20v20"/>',box:'<path d="m3 7 9-5 9 5-9 5-9-5Zm0 0v11l9 5 9-5V7M12 12v11M7 4l10 6"/>',heart:'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',plus:'<path d="M12 4v16M4 12h16"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',home:'<path d="m3 10 9-7 9 7v11h-7v-7h-4v7H3z"/>',help:'<circle cx="12" cy="12" r="10"/><path d="M9 8a3 3 0 1 1 5 2c-2 1-2 2-2 3m0 3v1"/>',share:'<circle cx="18" cy="4" r="3"/><circle cx="5" cy="12" r="3"/><circle cx="18" cy="20" r="3"/><path d="m8 10 7-4M8 14l7 4"/>',stop:'<rect x="6" y="6" width="12" height="12" rx="1"/>',settings:'<path d="M4 5h16M4 12h16M4 19h16"/><circle cx="8" cy="5" r="2" fill="currentColor"/><circle cx="16" cy="12" r="2" fill="currentColor"/><circle cx="10" cy="19" r="2" fill="currentColor"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 1v2m0 18v2M1 12h2m18 0h2M4 4l2 2m12 12 2 2M4 20l2-2M18 6l2-2"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4"/>',gift:'<rect x="3" y="8" width="18" height="4"/><path d="M5 12v9h14v-9M12 8v13M12 8C2 8 5-1 10 4l2 4Zm0 0c10 0 7-9 2-4l-2 4Z"/>',info:'<circle cx="12" cy="12" r="10"/><path d="M12 10v7m0-11v1"/>',leaf:'<path d="M20 3C5 1 1 10 5 16s15 4 15-13Z"/><path d="m3 22 12-13"/>',copy:'<rect x="8" y="8" width="13" height="13" rx="2"/><path d="M16 8V3H3v13h5"/>',file:'<path d="M14 2H4v20h16V8zM14 2v6h6M8 12h8m-8 4h8"/>'};
const icon=(name)=>`<svg class="ui-icon" width="21" height="21" aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round">${icons[name]||icons.box}</svg>`;
const defaults={scale:1,contrast:false,motion:false,focus:false,rate:.9};
const storedSettings=safeStorageGet('tm-settings',{});
const settings={...defaults,...(storedSettings&&typeof storedSettings==='object'?storedSettings:{})};
settings.scale=[1,1.15,1.3].includes(settings.scale)?settings.scale:1;
settings.rate=[.75,.9,1.1].includes(settings.rate)?settings.rate:.9;
let custom=safeStorageGet('tm-products',[]);
custom=Array.isArray(custom)?custom.filter(p=>p&&typeof p.id==='string'&&Array.isArray(p.variants)&&Array.isArray(p.colors)&&p.variants[0]?.includes).slice(0,30):[];
let savedCart=safeStorageGet('tm-cart',[]);
savedCart=Array.isArray(savedCart)?savedCart.filter(i=>i&&typeof i.key==='string'&&typeof i.name==='string'&&Array.isArray(i.includes)).slice(0,20).map(i=>({...i,quantity:Math.max(1,Math.min(99,Math.floor(Number(i.quantity)||1))),unitPrice:Number.isFinite(i.unitPrice)&&i.unitPrice>=0?i.unitPrice:null})):[];
const state={view:'home',productId:'cup',variantIndex:1,colorIndex:0,act:0,demoOpen:false,step:0,heroGift:false,exploded:false,compareA:0,compareB:1,onlyDiff:false,query:'',category:'全部',cart:savedCart,note:String(safeStorageGet('tm-note','')).slice(0,500),budget:String(safeStorageGet('tm-budget','')).slice(0,10),transcript:'',checked:[false,false,false],shared:null,removed:null};
const root=document.getElementById('app'), modal=document.getElementById('modal');
let returnFocus=null,returnFocusKey=null,toastTimer,voiceToken=0;
const products=()=>[...catalogue,...custom];
const product=()=>products().find(p=>p.id===state.productId)||catalogue[0];
const variant=()=>product().variants[state.variantIndex]||product().variants[0];
const color=()=>product().colors[state.colorIndex]||product().colors[0];
const art=(p,v,c,open=false,compact=false)=>productArt(p.kind,{color:c.hex,open,variant:v.id,compact});
const btn=(action,label,cls='secondary',ic='',attrs='')=>`<button type="button" class="${cls}" data-action="${action}" ${attrs}>${ic?icon(ic):''}${label}</button>`;
const sampleLabel=p=>p.source==='自己录入'?'自己录入 · 购买前核对':'示例商品 · 非真实售卖';
const productGallery={
 cup:{number:'01',title:'把温暖，握在手里。',mood:'森林绿 · 金属微光',description:'细腻的绿色杯身，和落在金属边缘的一道光。喜欢之后，再把开盖方式、容量与包装一项项看清。',alt:'森林绿金属保温杯立在暖色石台上，杯盖带有按键，金属边缘映出柔和高光'},
 lamp:{number:'02',title:'为日常，留一盏柔光。',mood:'燕麦白 · 暖光时刻',description:'圆润的灯罩，温柔的暖光。再走近一步，看看开关怎么用、供电方式和包装配件有什么不同。',alt:'奶白色台灯置于暖色石台上，锥形灯罩、细灯杆和圆形底座带有细致金属装饰'},
 box:{number:'03',title:'小小世界，井井有条。',mood:'暖象牙 · 秩序之美',description:'一只盒子的精致，藏在每一格里。打开盖子，再确认尺寸、数量，以及这一单真正包含的东西。',alt:'暖象牙白分格收纳盒的盒盖悬在上方，空的分格清晰可见，放在层叠石台上'},
 umbrella:{number:'04',title:'雨天，也有好心情。',mood:'深苔绿 · 雨的光泽',description:'雨珠落在伞面，映出细腻的织物光泽。把开合动作演一遍，自动与手动的差别就更明白。',alt:'深绿色折叠伞完整打开，细密伞骨、伞柄与伞面水滴可见，悬在石材展台上'}
};
const galleryImage=(id,cls='',eager=false)=>`<img class="${cls}" src="./assets/products/${id}-premium.jpg" alt="${e(productGallery[id].alt)}" width="1254" height="1254" loading="${eager?'eager':'lazy'}" decoding="async" ${eager?'fetchpriority="high"':''}>`;
function galleryDialog(id){const p=catalogue.find(x=>x.id===id),g=productGallery[id];if(!p||!g)return;openModal(`${g.number} / ${e(p.name)}`,`<div class="gallery-layout"><div class="gallery-image">${galleryImage(id,'',true)}<span class="gallery-image-label">AI 商品概念图</span></div><div class="gallery-copy"><div class="section-kicker">${g.mood}</div><h3>${g.title}</h3><p>${g.description}</p><div class="gallery-price">${money(p.variants[0].price)}<small>起 · 示例价</small></div><div class="gallery-thumbnails" role="group" aria-label="切换展映商品">${catalogue.map(x=>`<button data-action="gallery" data-id="${x.id}" aria-label="欣赏${e(x.name)}" aria-pressed="${id===x.id}" class="${id===x.id?'selected':''}">${galleryImage(x.id)}</button>`).join('')}</div>${btn('gallery-start','进入这件宝贝的小剧场','primary','play',`data-id="${id}"`)}<p class="fine-print">概念图展示设计氛围；规格、颜色及包含内容请在小剧场中逐项查看。</p></div></div>`);modal.classList.add('gallery-dialog');}


function applySettings(){document.documentElement.style.setProperty('--scale',settings.scale);document.documentElement.classList.toggle('high-contrast',!!settings.contrast);document.body.classList.toggle('no-motion',!!settings.motion);document.body.classList.toggle('focus-mode',!!settings.focus);}
function announce(text){const el=document.getElementById('announcer');el.textContent='';setTimeout(()=>el.textContent=text,30);}
function toast(text){const el=document.getElementById('toast');clearTimeout(toastTimer);el.textContent=text;el.classList.add('show');announce(text);toastTimer=setTimeout(()=>el.classList.remove('show'),4200);}
function persist(){if(!safeStorageSet('tm-cart',state.cart))toast('浏览器未允许保存。请下载清单，避免关闭后丢失。');}
function stopSpeech(){voiceToken++;if('speechSynthesis'in window)window.speechSynthesis.cancel();}
function speak(text){stopSpeech();state.transcript=text;render();if(!('speechSynthesis'in window)||!('SpeechSynthesisUtterance'in window)){toast('这个浏览器暂不支持讲解，完整文字已显示，可使用设备读屏。');return;}
 const token=voiceToken;const utterance=new SpeechSynthesisUtterance(text);utterance.lang='zh-CN';utterance.rate=settings.rate;const voices=speechSynthesis.getVoices();const voice=voices.find(v=>/^zh[-_]CN/i.test(v.lang))||voices.find(v=>/^zh/i.test(v.lang));if(voice)utterance.voice=voice;
 utterance.onerror=event=>{if(token===voiceToken&&!['interrupted','canceled'].includes(event.error))toast('讲解未能播放，文字讲解仍可查看。请检查设备语音设置。');};speechSynthesis.speak(utterance);announce('正在讲解，页面上也保留了完整文字。');}

function header(){return `<header class="site-header"><div class="wrap header-inner"><button class="brand" data-action="home" aria-label="淘明白，返回首页"><img src="./assets/icon.svg" alt=""><span><strong>淘明白</strong><small>把选择留给你</small></span></button><nav class="desktop-nav" aria-label="主要导航">${[['home','逛一逛'],['theater','宝贝小剧场'],['cart','我的清单']].map(([v,t])=>`<button class="nav-button ${state.view===v?'active':''}" data-action="${v}" ${state.view===v?'aria-current="page"':''}>${t}${v==='cart'&&state.cart.length?`<span class="count">${state.cart.length}</span>`:''}</button>`).join('')}</nav><div class="header-tools">${btn('settings','<span>看得更清楚</span>','utility','eye','aria-label="打开阅读与无障碍设置"')}${btn('help','','icon-button','help','aria-label="使用帮助"')}</div></div></header>`;}
function footer(){return `<footer class="site-footer"><div class="wrap footer-inner"><p>淘明白 · 淘宝创意作品，非淘宝官方服务。示例价格不代表真实报价，不执行付款。<br>你录入的资料和清单保存在当前浏览器；分享后，持有链接的人可查看分享内容。</p><div class="footer-links">${btn('about','关于这份创意','','')}${btn('privacy','资料与隐私','','')}${btn('help','使用帮助','','')}</div></div></footer><nav class="mobile-nav" aria-label="移动端导航">${[['home','逛一逛','home'],['theater','小剧场','play'],['cart','我的清单','bag'],['settings','阅读设置','eye']].map(([a,t,i])=>`<button data-action="${a}" class="${state.view===a?'active':''}" ${state.view===a?'aria-current="page"':''}>${icon(i)}<span>${t}${a==='cart'&&state.cart.length?` · ${state.cart.length}`:''}</span></button>`).join('')}</nav>`;}
function focusKey(el){if(!el||el===document.body)return null;return {id:el.id||'',data:{...el.dataset},scope:el.closest('.mobile-nav')?'mobile':el.closest('.desktop-nav')?'desktop':el.closest('dialog')?'dialog':'page',selection:el.selectionStart};}
function restoreFocus(key,fallback=false){if(!key)return;let el=key.id?document.getElementById(key.id):null;if(!el&&key.data.action){const scope=key.scope==='mobile'?document.querySelector('.mobile-nav'):key.scope==='desktop'?document.querySelector('.desktop-nav'):key.scope==='dialog'?modal:document;el=[...scope.querySelectorAll('[data-action]')].find(x=>Object.entries(key.data).every(([k,v])=>x.dataset[k]===v));}if(el?.disabled)el=el.closest('.quantity')?.querySelector('button:not(:disabled)')||null;if(!el&&fallback)el=document.getElementById('act-'+state.act)||document.getElementById('main');if(el){el.focus({preventScroll:true});if(typeof key.selection==='number'&&el.setSelectionRange){try{el.setSelectionRange(key.selection,key.selection)}catch{}}}}
function render(){const key=focusKey(document.activeElement);applySettings();root.innerHTML=header()+`<main id="main" tabindex="-1" class="wrap">${state.view==='home'?home():state.view==='theater'?theater():state.view==='cart'?cart():shared()}</main>`+footer();if(!modal.open)restoreFocus(key,true);}

function go(view){if(view!=='shared'&&location.hash.startsWith('#list='))history.replaceState(null,'',location.pathname+location.search);stopSpeech();state.transcript='';state.view=view;render();window.scrollTo({top:0,behavior:'instant'});document.getElementById('main').focus({preventScroll:true});}
function selectProduct(id){state.productId=id;state.variantIndex=id==='cup'?1:0;state.colorIndex=0;state.act=0;state.demoOpen=false;state.step=0;state.compareA=0;state.compareB=product().variants.length>1?1:0;state.exploded=false;state.checked=[false,false,false];go('theater');}
function selectVariant(index){state.variantIndex=index;state.demoOpen=false;state.step=0;state.checked=[false,false,false];state.transcript='';stopSpeech();render();announce(`已换成${variant().label}，${money(variant().price)}。包装清单已同步更新。`);}

function home(){const p=catalogue[0],v=p.variants[state.heroGift?2:1];const list=products().filter(p=>(state.category==='全部'||(state.category==='自己录入'?p.source==='自己录入':p.category===state.category))&&`${p.name} ${p.tags.join(' ')} ${p.summary}`.includes(state.query.trim()));return `<section class="hero" aria-labelledby="hero-title"><div class="hero-copy"><div class="eyebrow"><span class="eyebrow-line" aria-hidden="true"></span>每一份喜欢，都值得自己选择</div><h1 id="hero-title">这一次，<br><em>我自己挑。</em></h1><p>看清楚、听明白，再慢慢选。<br>让复杂的商品说明，变成眼前的三幕小剧场。</p><div class="hero-actions">${btn('start','开启我的小剧场','primary','play')}${btn('intro-audio','听听怎么用','secondary','audio')}</div><div class="tiny-benefits"><span>${icon('eye')}大字与高对比</span><span>${icon('audio')}随时听讲解</span><span>${icon('heart')}不催促，自己选</span></div></div><div class="hero-stage"><div class="stage-top"><span class="pill">日常好物 · 光影展映</span><span class="edition-number">01 / 04</span></div><div class="hero-scene ${state.heroGift?'gift':''}" aria-label="${state.heroGift?'礼盒款，多了礼盒和空白心意卡':'按键款，只有杯子与杯盖，不含礼盒'}"><div class="hero-product">${galleryImage('cup','hero-photo',true)}</div><button class="hero-gallery-button" data-action="gallery" data-id="cup" aria-label="放大欣赏日常随行保温杯">${icon('eye')}放大欣赏</button><span class="hero-image-label">AI 商品概念图</span>${state.heroGift?'<div class="hero-gift" aria-hidden="true"><div class="gift-box"></div><span class="gift-card">给你的一份心意</span></div>':''}<div class="scene-note">${icon('check')}<span>${state.heroGift?'同一只杯子<br>多一份心意':'把喜欢的东西<br>看得更明白'}</span></div></div><div class="stage-options" role="group" aria-label="切换包装体验">${btn('hero-single','只要杯子','chip '+(!state.heroGift?'selected':''),'',`aria-pressed="${!state.heroGift}" id="hero-single"`)}${btn('hero-gift','加一份心意','chip '+(state.heroGift?'selected':''),'gift',`aria-pressed="${state.heroGift}" id="hero-gift"`)}</div><p class="stage-caption">${state.heroGift?'礼盒款示例价 ¥89 · 多出的内容，摆给你看':'点一下「加一份心意」，看看有什么变化'}</p></div></section><div class="how-grid" aria-label="购物小剧场的三幕">${[['play','01 · 怎么用','关键动作，演一遍就更清楚。'],['compare','02 · 差在哪','把不同规格放在一起，慢慢比。'],['box','03 · 收到什么','摊开这一单，不让配件藏起来。']].map(([i,t,d])=>`<div class="how-item"><div class="how-icon">${icon(i)}</div><div><h3>${t}</h3><p>${d}</p></div></div>`).join('')}</div><section aria-labelledby="catalogue-title" id="catalogue"><div class="section-heading"><div><div class="section-kicker">日常好物 / 四种心动</div><h2 id="catalogue-title">好好看，也看明白。</h2><p>不用读完长长的详情页，也能把选择弄明白。</p></div>${btn('import','放入自己的商品','text-button','plus')}</div><div class="catalogue-tools"><div class="filters" role="group" aria-label="按类型筛选">${['全部','喝水与随行','居家小物',...(custom.length?['自己录入']:[])].map(t=>btn('filter',e(t),'chip '+(state.category===t?'selected':''),'',`data-value="${e(t)}" aria-pressed="${state.category===t}" id="filter-${e(t)}"`)).join('')}</div><label class="searchbox"><span class="sr-only">搜索商品名称或特点</span>${icon('search')}<input id="product-search" type="search" placeholder="找找你想了解的商品" value="${e(state.query)}" maxlength="100" autocomplete="off"></label></div><div class="product-grid">${list.length?list.map(productCard).join(''):`<div class="empty-state">${icon('search')}<h3>暂时没有找到这件商品</h3><p>换个词试试，或者放入你自己的商品资料。</p>${btn('clear-search','清除筛选','secondary')}${btn('import','录入商品','text-button','plus')}</div>`}</div><p class="product-note">${icon('info')} 内置商品及 AI 概念图均为示例，帮助你体验完整流程。真实购物时，可录入自己找到的商品资料并逐项核对。</p></section><section class="bring-own"><div class="bring-icon">${icon('file')}</div><div><h3>看中了一件别的宝贝？</h3><p>粘贴商品文字，整理规格与包装清单。信息留在你的浏览器里。</p></div>${btn('import','整理我的商品','secondary','arrow')}</section><section class="story-strip"><blockquote>“这次的生日礼物，<br>想等你拆开，才告诉你是我挑的。”</blockquote><p>我们相信，帮助一个人看明白商品，也是在为他留住自己选择、送出惊喜的机会。</p></section>${transcript()}`;}
function productCard(p){const v=p.variants[0],g=productGallery[p.id];return `<article class="product-card ${g?'editorial-card':''}"><div class="product-visual ${g?'photo-visual':''}">${g?galleryImage(p.id,'product-photo'):art(p,v,p.colors[0],false,true)}<span class="pill">${p.source==='自己录入'?'自己录入':'可听 · 可看 · 可操作'}</span>${g?`<span class="product-edition" aria-hidden="true">${g.number}</span><div class="visual-caption"><span>${g.mood}</span><strong>${g.title}</strong></div>`:''}</div><div class="product-info"><div class="category">${e(p.category)} / ${p.variants.length} 种选择</div><h3>${e(p.name)}</h3><p>${e(p.kicker)}</p><div class="product-bottom"><div class="product-price">${money(v.price)}<small>${p.source==='自己录入'?'录入价格':'起 · 示例价'}</small></div><span class="card-cta">进入小剧场<span class="round-arrow" aria-hidden="true">${icon('arrow')}</span></span></div></div><button class="product-main-link" data-action="product" data-id="${e(p.id)}" aria-label="了解${e(p.name)}，${p.variants.length}种规格，进入小剧场"></button>${g?btn('gallery',`${icon('eye')}<span>放大欣赏</span>`,'gallery-open','',`data-id="${p.id}" aria-label="放大欣赏${e(p.name)}"`):''}</article>`;}

function transcript(){return state.transcript?`<div class="transcript"><strong>本次讲解文字</strong><p>${e(state.transcript)}</p>${btn('stop-speech','停止讲解','text-button','stop')}</div>`:'';}

function theater(){const p=product(),v=variant(),c=color();return `<div class="page-intro"><button class="back-button" data-action="home">${icon('back')}回到逛一逛</button><div class="eyebrow">你的宝贝小剧场</div><h1>慢慢看，选得更明白。</h1><p>每个选项都能看见结果，每一步都可以重新选择。</p></div><div class="theater-layout"><section class="theater-panel" aria-label="三幕商品体验"><nav class="act-tabs" aria-label="选择剧幕">${['怎么用','差在哪','收到什么'].map((name,i)=>`<button id="act-${i}" class="act-tab ${state.act===i?'active':''}" data-action="act" data-index="${i}" ${state.act===i?'aria-current="step"':''}><b>0${i+1}</b>${name}</button>`).join('')}</nav>${state.act===0?usageAct(p,v,c):state.act===1?compareAct(p,c):packingAct(p,v,c)}<div class="act-footer"><span>第 ${state.act+1} 幕 / 共 3 幕</span>${state.act>0?btn('previous-act','上一幕','secondary','back'):''}${state.act<2?btn('next-act',state.act===0?'看看差在哪':'看看收到什么','primary','arrow'):btn('add-cart','放入我的清单','primary','bag')}</div></section><aside class="details-panel" aria-label="选择商品规格"><span class="record-tag">${sampleLabel(p)}</span><h2>${e(p.name)}</h2><p>${e(p.kicker)}</p><div class="price-line"><strong>${money(v.price)}</strong><small>${p.source==='自己录入'?'你录入的单价':'当前规格 · 示例价'}</small></div><span class="field-label" id="variant-label">先选一个规格</span><div class="option-stack" role="group" aria-labelledby="variant-label">${p.variants.map((x,i)=>`<button id="variant-${i}" class="variant-option ${state.variantIndex===i?'selected':''}" data-action="variant" data-index="${i}" aria-pressed="${state.variantIndex===i}"><span>${e(x.label)}<small>${e(x.capacity)}</small></span><strong>${money(x.price)}</strong></button>`).join('')}</div><span class="field-label" id="color-label">再选喜欢的颜色：${e(c.name)}</span><div class="colors" role="group" aria-labelledby="color-label">${p.colors.map((x,i)=>`<button id="color-${i}" class="color-choice ${state.colorIndex===i?'selected':''}" data-action="color" data-index="${i}" aria-pressed="${state.colorIndex===i}"><span class="swatch" style="background:${/^#[0-9a-f]{6}$/i.test(x.hex)?x.hex:'#ccc'}" aria-hidden="true"></span>${e(x.name)}</button>`).join('')}</div><div class="purchase-actions">${btn('read-selection','听听我的选择','secondary','audio')}${btn('packing','摊开这一单','primary','box')}</div><p class="fine-print">${p.source==='自己录入'?'此商品由你录入，图形仅为分类示意，不代表实物外观或操作。购买前请核对原商品页。':'图形为操作与配置示意，不代表实物外观、比例或性能。这里不会产生订单或付款。'}</p>${p.source==='自己录入'?btn('edit-custom','修改这条资料','text-button','file')+btn('remove-custom','删除这条录入','text-button','','data-id="'+e(p.id)+'"'):''}</aside></div>${transcript()}`;}
function usageAct(p,v,c){const current=v.steps[state.step]||v.steps[0];return `<div class="theater-stage ${state.demoOpen?'is-demonstrating':''}"><span class="stage-orbit" aria-hidden="true"></span><span class="pill stage-badge">${p.source==='自己录入'?'分类示意':'操作示意 · 可反复播放'}</span><span class="stage-wordmark" aria-hidden="true">TAOMINGBAI</span><div class="main-art">${art(p,v,c,state.demoOpen)}</div><span class="stage-caption-card">${state.demoOpen?e(v.method):'点下方按钮，看看操作变化'}</span></div><div class="act-content"><div class="section-kicker">01 / 让动作说清楚</div><h2>${p.source==='自己录入'?'先看清你录入的信息':'试一下，它怎么用？'}</h2><p>${e(v.method)}</p><div class="play-row">${btn('demo',state.demoOpen?'收起演示':'演给我看','primary',state.demoOpen?'stop':'play','id="demo-toggle" aria-pressed="'+state.demoOpen+'"')}${btn('read-step','听这一小步','secondary','audio')}</div><div class="step-list" aria-label="操作步骤">${v.steps.map((step,i)=>`<button id="step-${i}" class="step-item ${state.step===i?'current':''}" data-action="step" data-index="${i}" aria-pressed="${state.step===i}"><span class="step-number">${i+1}</span><span><strong>${e(step.title)}</strong><p>${e(step.detail)}</p></span></button>`).join('')}</div><details><summary class="toggle-line">还有哪些信息需要向商家确认？</summary><div class="notice neutral">${v.unknowns.map(t=>`<p>• ${e(t)}</p>`).join('')}${btn('seller-questions','复制要问商家的问题','text-button','copy')}</div></details></div>`;}
function compareAct(p,c){const a=p.variants[state.compareA]||p.variants[0],b=p.variants[state.compareB]||p.variants[0];const rows=[['价格',money(a.price),money(b.price)],['规格',a.capacity,b.capacity],['操作方式',a.method,b.method],['尺寸',a.dimensions,b.dimensions],['重量',a.weight,b.weight],['包含的东西',a.includes.map(i=>`${i.name} × ${i.qty}`).join('、'),b.includes.map(i=>`${i.name} × ${i.qty}`).join('、')],['不包含',a.excludes.join('、')||'未明确',b.excludes.join('、')||'未明确']];return `<div class="compare-stage">${[a,b].map((v,i)=>`<div class="compare-item"><label for="compare-${i}">${i===0?'左边看这款':'右边看这款'}</label><select id="compare-${i}" data-compare="${i}" ${p.variants.length===1?'disabled':''}>${p.variants.map((x,j)=>`<option value="${j}" ${x.id===v.id?'selected':''}>${e(x.label)}</option>`).join('')}</select>${art(p,v,c,false,true)}<div class="compare-price">${money(v.price)}</div>${btn('choose-compare','选这一款','text-button','check',`data-index="${p.variants.indexOf(v)}"`)}</div>`).join('')}</div><div class="act-content"><div class="section-kicker">02 / 不同的地方，摆在一起</div><h2>贵在哪里，少了什么？</h2><p>${p.variants.length===1?'这件商品暂时只有一个录入规格。可在录入时补充另一个规格，再进行对比。':'黄色标记的是差异。价格高低只是其中一项，你在意什么，就先看什么。'}</p><div class="play-row">${btn('read-compare','听听两款差别','secondary','audio')}</div><label class="toggle-line"><input id="only-diff" type="checkbox" ${state.onlyDiff?'checked':''}>只看不同的地方</label><div class="table-wrap"><table class="compare-table"><caption class="sr-only">${e(a.label)}与${e(b.label)}规格对比</caption><thead><tr><th scope="col">比较内容</th><th scope="col">${e(a.label)}</th><th scope="col">${e(b.label)}</th></tr></thead><tbody>${rows.filter(r=>!state.onlyDiff||r[1]!==r[2]).map(([label,av,bv])=>`<tr class="${av!==bv?'different':''}"><th scope="row">${label}</th><td>${e(av||'未提供')}</td><td>${e(bv||'未提供')}</td></tr>`).join('')||'<tr><td colspan="3">这两个选择没有已记录的差异。</td></tr>'}</tbody></table></div><p class="legend">不同的内容也使用文字表达，不只靠颜色区分。</p></div>`;}
function packingArt(item,p,v,c){if(['cup','lamp','box','umbrella'].includes(item.kind))return art({...p,kind:item.kind},{...v,id:({gift:'daily',complete:'dimming',pair:'large',case:'auto'})[v.id]||v.id},c,false,true);return `<div class="packing-icon">${icon(item.kind==='gift'?'gift':item.kind==='card'?'file':item.kind==='cable'?'settings':'box')}</div>`;}
function packingAct(p,v,c){return `<div class="unbox-intro ${state.exploded?'revealed':''}"><div class="section-kicker">03 / 把这一单摊开</div><h2>这次，收到的就是这些。</h2><div class="parcel ${state.exploded?'open':''}" aria-hidden="true"><div class="parcel-aura"></div><div class="parcel-body"></div><div class="parcel-lid"></div></div>${btn('unbox',state.exploded?'重新合上清单':'拆开看看，都有什么','primary','box',`id="unbox-toggle" aria-expanded="${state.exploded}" aria-controls="packing-contents"`)}<p class="stage-caption">这是所选配置的可视化清单，不是真实物流包裹。</p></div><div class="act-content" id="packing-contents">${state.exploded?`<h2>${e(v.label)} · ${e(c.name)}</h2><div class="packing-grid">${v.includes.map((item,i)=>`<div class="packing-card" style="--reveal-order:${i}">${packingArt(item,p,v,c)}<strong>${e(item.name)}</strong><span>数量 ${item.qty}</span></div>`).join('')}</div><div class="notice"><strong>这一单不包含：</strong>${e(v.excludes.join('、')||'尚未明确，请向商家确认')}。</div><dl class="summary-facts"><div><dt>所选颜色</dt><dd>${e(c.name)}</dd></div><div><dt>${p.source==='自己录入'?'录入单价':'当前规格示例价'}</dt><dd>${money(v.price)}</dd></div></dl>${btn('read-selection','完整听一遍','secondary','audio')}<div class="checklist" aria-label="自愿核对清单">${['款式和颜色，是我想要的','包含和不包含的东西，我已看清','这份价格需要到淘宝结算页再次核对'].map((t,i)=>`<label><input type="checkbox" data-check="${i}" ${state.checked[i]?'checked':''}>${t}</label>`).join('')}</div><p class="fine-print">勾选帮助你逐项记住，不是强制考试。随时可以回到上一幕重新选择。</p>`:`<p>点「拆开看看」，杯子、配件、包装会分别出现。换一个规格，再看看清单如何变化。</p>`}</div>`;}

function cart(){const summary=summarizeCart(state.cart);return `<div class="page-intro"><div class="eyebrow">选择是你的，节奏也是</div><div class="cart-title-line"><h1>我的明白清单</h1>${btn('import','再放入一件商品','secondary','plus')}</div><p>先放在这里，想清楚再决定。清单不会自动下单。</p></div>${state.removed?`<div class="notice neutral">刚刚移除了「${e(state.removed.item.name)}」。${btn('undo-remove','撤销移除','text-button','back')}</div>`:''}${!state.cart.length?`<div class="empty-state" style="margin-bottom:50px">${icon('bag')}<h2>给喜欢的东西，留个位置。</h2><p>去小剧场选好一款，再放进清单。也可以整理自己的淘宝商品。</p>${btn('home','去逛一逛','primary','arrow')}${btn('import','录入自己的商品','text-button','plus')}</div>`:`<div class="cart-layout"><div class="cart-items">${state.cart.map((item,i)=>`<article class="cart-item"><div class="cart-art">${productArt(item.kind||'cup',{color:item.hex||'#91a798',variant:item.variantId,compact:true})}</div><div><span class="record-tag">${e(item.source)}</span><h3>${e(item.name)}</h3><p>${e(item.variant)} · ${e(item.color)}</p><p>包含：${e(item.includes.join('、'))}</p>${item.excludes?.length?`<p>不包含：${e(item.excludes.join('、'))}</p>`:''}<p class="cart-price">${money(item.unitPrice)} / 套</p><div class="cart-row"><div class="quantity" role="group" aria-label="${e(item.name)}数量"><button data-action="quantity" data-index="${i}" data-delta="-1" aria-label="减少${e(item.name)}数量" ${item.quantity<=1?'disabled':''}>−</button><span aria-label="数量${item.quantity}">${item.quantity}</span><button data-action="quantity" data-index="${i}" data-delta="1" aria-label="增加${e(item.name)}数量" ${item.quantity>=99?'disabled':''}>+</button></div><button class="remove" data-action="remove-item" data-index="${i}">移除<span class="sr-only">${e(item.name)}</span></button></div>${item.sourceUrl?`<a class="text-button" href="${e(validateSourceUrl(item.sourceUrl))}" target="_blank" rel="noopener noreferrer">回到淘宝原商品页 ${icon('arrow')}</a>`:''}</div></article>`).join('')}<div class="import-callout"><span>${icon('heart')} 还没决定也没关系，清单会为你留着。</span>${btn('home','继续逛逛','text-button','arrow')}</div></div><aside class="cart-summary"><h2>把这一单算清楚</h2><div class="total-line"><span>${summary.count} 套商品${summary.unknown?' · 已知金额合计':''}</span><strong>${money(summary.total)}</strong></div>${summary.unknown?`<div class="notice">另有 ${summary.unknown} 套价格待确认，不计入此合计。</div>`:''}<p class="fine-print">包含示例或手动录入价格；未计运费与优惠。真实金额以淘宝结算页为准。</p><label class="field-label" for="budget">给自己定个预算（选填）</label><input id="budget" class="form-control" inputmode="decimal" type="number" min="0" max="10000000" step="0.01" placeholder="例如 200 元" value="${e(state.budget)}"><p id="budget-status" class="budget-status">${budgetText(summary)}</p><label class="field-label" for="cart-note">留一句心意或提醒（选填）</label><textarea id="cart-note" class="form-control" maxlength="500" placeholder="例如：想给妈妈挑的生日礼物，先确认开盖是否方便。">${e(state.note)}</textarea>${btn('read-cart','听听完整清单','secondary','audio')}${btn('share','生成分享卡','primary','share')}${btn('download','下载文字清单','secondary','download')}${btn('print','打印这份清单','text-button','file')}</aside></div>`}${transcript()}`;}
function budgetText(summary){const b=Number(state.budget);if(!state.budget||!Number.isFinite(b)||b<0)return'预算只帮你记账，不会影响商品排序。';if(summary.unknown)return'有商品价格待确认，暂时无法判断是否在预算内。';return summary.total>b?`超过预算 ${money(summary.total-b)}。可以先移除不急着买的。`:`在预算内，还余 ${money(b-summary.total)}。不需要为了用满预算而多买。`;}
function shared(){const s=state.shared;if(!s)return `<div class="page-intro"><h1>这份分享暂时打不开</h1><p>链接可能不完整。请让分享者重新复制完整链接。</p>${btn('home','回到首页','primary','home')}</div>`;const sum=summarizeCart(s.items);return `<div class="page-intro"><div class="eyebrow">一份认真挑好的心意</div><h1>${e(s.title||'这一次，我自己挑。')}</h1></div><section class="share-card"><span class="record-tag">分享清单 · 不会自动购买</span><h2>想把这份选择，告诉你。</h2>${s.note?`<div class="share-note">${e(s.note)}</div>`:''}<ul class="share-list">${s.items.map(i=>`<li><h3>${e(i.name)} × ${i.quantity}</h3><p>${e(i.variant)} · ${e(i.color)} · 单价 ${money(i.unitPrice)}</p><p>包含：${e(i.includes.join('、'))}</p>${i.note?`<p>${e(i.note)}</p>`:''}</li>`).join('')}</ul><div class="total-line"><span>${sum.unknown?'已知金额合计':'清单金额'}</span><strong>${money(sum.total)}</strong></div><p class="fine-print">${sum.unknown?`另有 ${sum.unknown} 套价格待确认。`:''}资料来自分享者，可能包含示例商品。请以淘宝原商品页和结算信息为准。</p><div class="share-actions">${btn('read-shared','听这份清单','secondary','audio')}${btn('download-shared','保存文字清单','primary','download')}${btn('home','我也来挑一份','secondary','arrow')}</div></section>${transcript()}`;}

function openModal(title,body){modal.classList.remove('gallery-dialog');const wasOpen=modal.open;const previous=wasOpen?focusKey(document.activeElement):null;if(!wasOpen){returnFocus=document.activeElement;returnFocusKey=focusKey(returnFocus);}modal.innerHTML=`<div class="dialog-head"><h2 id="modal-title" tabindex="-1">${title}</h2>${btn('close-modal','','icon-button','close','aria-label="关闭对话框"')}</div><div class="dialog-body">${body}</div>`;if(!wasOpen)modal.showModal();document.getElementById('modal-title').focus();if(previous)restoreFocus(previous);}
function closeModal(){modal.close();if(returnFocus?.isConnected)returnFocus.focus();else restoreFocus(returnFocusKey,true);}

function settingsDialog(){openModal('用你舒服的方式逛',`<p>设置只保存在当前浏览器。你随时可以调整。</p><div class="setting-group"><h3>文字大小</h3><div class="segmented" role="group" aria-label="文字大小">${[[1,'标准'],[1.15,'大字'],[1.3,'特大字']].map(([n,t])=>btn('setting-scale',t,settings.scale===n?'selected':'','',`data-value="${n}" aria-pressed="${settings.scale===n}"`)).join('')}</div></div><div class="setting-group"><h3>阅读偏好</h3><label class="toggle-line"><input type="checkbox" data-setting="contrast" ${settings.contrast?'checked':''}>高对比：深色底与亮色文字</label><label class="toggle-line"><input type="checkbox" data-setting="motion" ${settings.motion?'checked':''}>减少动态：关闭过渡动画</label><label class="toggle-line"><input type="checkbox" data-setting="focus" ${settings.focus?'checked':''}>专注模式：少一些装饰，慢慢走每一步</label></div><div class="setting-group"><h3>讲解速度</h3><div class="segmented" role="group" aria-label="讲解速度">${[[.75,'慢一点'],[.9,'自然'],[1.1,'快一点']].map(([n,t])=>btn('setting-rate',t,settings.rate===n?'selected':'','',`data-value="${n}" aria-pressed="${settings.rate===n}"`)).join('')}</div><p>讲解使用设备提供的语音。若设备没有中文语音，可使用页面文字和系统读屏。</p>${btn('test-voice','听一小段','text-button','audio')}</div><div class="dialog-actions">${btn('reset-settings','恢复默认','secondary')}${btn('close-modal','这样很舒服','primary','check')}</div>`);}
function helpDialog(){openModal('慢慢来，每一步都在这里',`<ul class="how-to"><li><strong>1. 先挑一件商品</strong>首页有四件示例商品。也可以粘贴自己的商品文字，确认资料后加入。</li><li><strong>2. 三幕可以自由切换</strong>“怎么用”看动作；“差在哪”比较规格；“收到什么”拆开清单。切换规格，内容会一起更新。</li><li><strong>3. 清单先替你记着</strong>你可以改数量、设预算、下载文字或生成分享链接。这里不会执行购买或收取费用。</li><li><strong>4. 关键信息可以听讲解</strong>点击带喇叭的讲解按钮。语音不可用时，讲解文字仍完整保留。读屏用户可按标题与按钮顺序浏览。</li></ul><p>键盘：<kbd class="keyboard-key">Tab</kbd> 移动，<kbd class="keyboard-key">Enter</kbd> 选择，<kbd class="keyboard-key">Esc</kbd> 关闭弹窗。<kbd class="keyboard-key">Alt + 1 / 2 / 3</kbd> 切换首页、小剧场、清单；<kbd class="keyboard-key">Alt + A</kbd> 打开阅读设置。</p><div class="dialog-actions">${btn('close-modal','我明白了','primary','check')}</div>`);}
function importDialog(){openModal('把自己的宝贝，放进小剧场',`<p>从淘宝复制商品标题、规格、价格和包装文字，粘贴到下面。本地整理后，你可以逐项修改；不会自动读取淘宝账号。</p><form id="import-extract"><div class="form-field"><label for="listing-text">商品资料</label><textarea class="form-control" id="listing-text" required minlength="2" maxlength="30000" rows="7" placeholder="例如：\n桌面收纳盒\n规格：大号单只装\n价格：39元\n包含：盒体、盒盖\n不含：图片中的文具"></textarea><small>不要粘贴地址、电话、订单号等个人资料。</small></div><div class="dialog-actions">${btn('import-example','填入一段示例','secondary')}<button class="primary" type="submit">整理成明白卡 ${icon('arrow')}</button></div></form>`);}
function importReview(text){const d=extractListing(text);const explicit=(pattern)=>text.split(/\r?\n/).find(line=>pattern.test(line.trim()))?.replace(pattern,'').trim()||'';const packageFields=extractPackageClauses(text);const explicitIncluded=packageFields.includes,explicitExcluded=packageFields.excludes;if(packageFields.needsReview)d.questions.push('包含与排除内容混在一起，请对照原文分别填写，避免记错。');const explicitVariant=explicit(/^规格[：:]\s*/)||d.capacity;openModal('核对一下，这是你想选的吗？',`<p>下面按明确文字整理，未确认的信息留给你填写。不会把优惠条件当成最终价格。</p><div class="notice">${d.questions.map(q=>`<p>• ${e(q)}</p>`).join('')}</div><form id="import-confirm"><div class="form-field"><label for="new-name">商品名称 *</label><input id="new-name" class="form-control" name="name" required maxlength="100" value="${e(d.title)}"></div><div class="field-row"><div class="form-field"><label for="new-kind">用哪种分类示意图</label><select id="new-kind" class="form-control" name="kind"><option value="box">通用包装 / 收纳</option><option value="cup">杯子</option><option value="lamp">台灯</option><option value="umbrella">雨伞</option></select></div><div class="form-field"><label for="new-color">所选颜色</label><input id="new-color" class="form-control" name="color" maxlength="30" placeholder="例如：米白色" value="待确认"></div></div><div class="field-row"><div class="form-field"><label for="new-variant">所选规格 *</label><input id="new-variant" class="form-control" name="variant" required maxlength="100" value="${e(explicitVariant)}" placeholder="例如：大号单只装"></div><div class="form-field"><label for="new-price">确认后的单价（元）</label><input id="new-price" class="form-control" name="price" type="number" step="0.01" min="0" max="10000000" value="${d.price??''}" placeholder="不确定就留空"></div></div><div class="form-field"><label for="new-includes">这一规格包含哪些东西 *</label><textarea id="new-includes" name="includes" class="form-control" required maxlength="1000" placeholder="每行一项，例如：\n盒体\n盒盖">${e(explicitIncluded)}</textarea><small>每行写“名称 × 数量”，如“杯子 × 2”。没写数量时按1件记录。图里的装饰物不一定包含。</small></div><div class="form-field"><label for="new-excludes">明确不包含的东西</label><input id="new-excludes" name="excludes" class="form-control" maxlength="300" placeholder="例如：文具、标签贴纸" value="${e(explicitExcluded)}"></div><details><summary class="toggle-line">再加一个规格，方便对比（选填）</summary><div class="field-row"><div class="form-field"><label for="alt-variant">另一个规格名称</label><input id="alt-variant" name="altVariant" class="form-control" maxlength="100" placeholder="例如：两只装"></div><div class="form-field"><label for="alt-price">另一个规格单价（元）</label><input id="alt-price" name="altPrice" class="form-control" type="number" min="0" max="10000000" step="0.01"></div></div><div class="form-field"><label for="alt-includes">另一个规格包含的东西</label><textarea id="alt-includes" name="altIncludes" class="form-control" maxlength="1000" placeholder="每行一项，需要分别核对"></textarea></div><div class="form-field"><label for="alt-excludes">另一个规格明确不包含</label><input id="alt-excludes" name="altExcludes" class="form-control" maxlength="300" placeholder="不清楚就留空，不沿用第一款"></div></details><div class="form-field"><label for="new-source">淘宝或天猫商品链接（选填）</label><input id="new-source" name="sourceUrl" class="form-control" type="url" maxlength="4096" placeholder="https://item.taobao.com/..."><small>支持淘宝 / 天猫的网址，不接受其他站点链接。</small></div><div class="form-field"><label for="new-notes">保留的原文 / 需要确认的事项</label><textarea id="new-notes" name="notes" class="form-control" maxlength="1200">${e(d.notes)}</textarea></div><label class="toggle-line"><input type="checkbox" name="confirmed" required>我已核对以上资料，知道它不是实时商品信息</label><p class="error-message" id="import-error" role="alert"></p><div class="dialog-actions">${btn('import','重新粘贴','secondary')}<button class="primary" type="submit">放进我的小剧场 ${icon('check')}</button></div></form>`);}
function saveImport(form){const fd=new FormData(form),get=k=>String(fd.get(k)||'').trim();const sourceUrl=get('sourceUrl');if(sourceUrl&&!validateSourceUrl(sourceUrl)){document.getElementById('import-error').textContent='链接需是淘宝或天猫的 http / https 网址。可以先清空链接，其他资料仍能保存。';return;}
 if(get('altVariant')&&!get('altIncludes')){document.getElementById('import-error').textContent='请填写另一个规格包含的东西，或清空另一个规格的名称。';return;}
 if(custom.length>=30&&!get('editId')){document.getElementById('import-error').textContent='当前浏览器已保存30件商品，请先删除不再需要的录入。';return;}
 const kind=get('kind'),note=get('notes'),id=get('editId')||'own-'+Date.now().toString(36);const toItems=parseIncludedLines;try{toItems(get('includes'));if(get('altVariant'))toItems(get('altIncludes'));}catch(err){document.getElementById('import-error').textContent=err.message;return;}const exclusions=t=>t.split(/[、,，;；]+/).map(x=>x.trim()).filter(Boolean);
 const makeVariant=(key,label,price,contents,excluded)=>({id:key,label,price:price===''?null:Number(price),capacity:label,method:'依据自己录入的资料核对，尚未提供真实操作演示',dimensions:'未提供',weight:'未提供',includes:toItems(contents),excludes:exclusions(excluded),facts:[{label:'资料来源',value:'用户自行录入'}],steps:[{title:'看清这一规格',detail:label},{title:'逐项核对包含内容',detail:contents},{title:'回到原商品页再确认',detail:note||'价格、库存、运费和实际功能仍需向商家核对。'}],unknowns:['需要在原商品页核对当前规格与价格','未验证实际功能、库存和配送信息']});
 const variants=[makeVariant('own-a',get('variant'),get('price'),get('includes'),get('excludes'))];if(get('altVariant'))variants.push(makeVariant('own-b',get('altVariant'),get('altPrice'),get('altIncludes'),get('altExcludes')));
 const p={id,name:get('name'),kicker:'你自己的资料，整理成明白的选择',category:'自己录入',kind,summary:note,tags:['自己录入','购买前核对'],colors:[{id:'own',name:get('color')||'待确认',hex:'#adb49c'}],variants,source:'自己录入',sourceUrl:validateSourceUrl(sourceUrl)};
 if(get('editId'))custom=custom.map(old=>old.id===id?p:old);else custom.push(p);if(!safeStorageSet('tm-products',custom))toast('已加入当前页面，但浏览器未允许长期保存。');closeModal();selectProduct(id);state.variantIndex=0;render();toast(get('editId')?'资料已更新。若清单中有旧版本，再次加入即可更新。':'已放进你的小剧场。先看看资料，再慢慢选。');}

function editCustom(){const p=product();importReview(p.summary||p.name);const f=document.getElementById('import-confirm');const hidden=document.createElement('input');hidden.type='hidden';hidden.name='editId';hidden.value=p.id;f.append(hidden);const set=(name,val)=>{f.elements.namedItem(name).value=val??'';};const first=p.variants[0];set('name',p.name);set('kind',p.kind);set('color',p.colors[0].name);set('variant',first.label);set('price',first.price);set('includes',first.includes.map(i=>i.name+' × '+i.qty).join('\n'));set('excludes',first.excludes.join('、'));set('sourceUrl',p.sourceUrl);set('notes',p.summary);if(p.variants[1]){const alt=p.variants[1];set('altVariant',alt.label);set('altPrice',alt.price);set('altIncludes',alt.includes.map(i=>i.name+' × '+i.qty).join('\n'));set('altExcludes',alt.excludes.join('、'));f.querySelector('details').open=true;}document.getElementById('modal-title').textContent='更新自己的商品资料';}

function addToCart(){const item=cartItem(product(),variant(),color());const exists=state.cart.find(x=>x.key===item.key);if(exists){if(item.source==='自己录入'){const quantity=exists.quantity;Object.assign(exists,item,{quantity});persist();render();toast('清单已更新为这份资料，保留了原来的数量。');}else toast('这款已经在清单里，可以在清单中调整数量。');return;}if(state.cart.length>=20){toast('清单最多20种商品。请先移除不需要的。');return;}state.cart.push(item);persist();render();toast('已放入清单，没有下单。你随时可以修改。');}
function listPayload(){return {version:1,title:'这一次，我自己挑。',items:state.cart.map(i=>({name:i.name,variant:i.variant,color:i.color,quantity:i.quantity,unitPrice:i.unitPrice,includes:i.includes,note:i.source==='自己录入'?'用户录入，购买前核对':'示例商品，非真实报价'})),note:state.note};}
function listText(payload){const sum=summarizeCart(payload.items);return `${payload.title}\n淘明白 · 我的明白清单\n\n${payload.note?'心意 / 提醒：'+payload.note+'\n\n':''}${payload.items.map((i,j)=>`${j+1}. ${i.name}\n规格：${i.variant}\n颜色：${i.color}\n数量：${i.quantity}\n单价：${money(i.unitPrice)}\n包含：${i.includes.join('、')}\n${i.note||''}`).join('\n\n')}\n\n已知金额合计：${money(sum.total)}${sum.unknown?'；另有'+sum.unknown+'套价格待确认':''}\n此清单可能包含示例或手动录入信息，未计运费优惠。真实信息以淘宝商品页和结算页为准，不是订单。`;} 
async function copyText(text){try{await navigator.clipboard.writeText(text);toast('已复制，可以粘贴到你想分享的地方。');return true;}catch{openModal('长按或全选复制',`<p>浏览器没有允许自动复制。你可以手动复制下面的内容。</p><textarea id="copy-fallback" class="form-control" rows="7" readonly>${e(text)}</textarea><div class="dialog-actions">${btn('close-modal','完成','primary')}</div>`);document.getElementById('copy-fallback').select();return false;}}
function downloadText(payload){const url=URL.createObjectURL(new Blob([listText(payload)],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='淘明白-我的购物清单.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('已生成文字文件，可保存或使用系统读屏阅读。');}
function shareDialog(){let url;try{url=location.origin+location.pathname+encodeSharedList(listPayload());}catch(err){toast(err.message||'清单过长，请减少内容后再分享。');return;}openModal('把选择变成一张心意卡',`<p>收件人能打开一张清楚的清单卡，也可以听讲解、保存文字。</p><div class="notice neutral">持有链接的人可以看到商品清单和你写下的心意。请不要包含地址、电话或订单号。分享是此刻的快照，之后改清单不会改变已发出的卡片。</div><label class="field-label" for="share-url">分享链接</label><input id="share-url" class="form-control" value="${e(url)}" readonly><div class="dialog-actions">${btn('preview-share','先看看卡片','secondary','eye')}${btn('copy-share','复制链接','primary','copy')}</div>`);}

document.addEventListener('click',async event=>{const target=event.target.closest('[data-action]');if(!target)return;const a=target.dataset.action;const index=Number(target.dataset.index);switch(a){
 case'gallery':galleryDialog(target.dataset.id);break;case'gallery-start':closeModal();selectProduct(target.dataset.id);break;case'home':go('home');break;case'theater':go('theater');break;case'cart':go('cart');break;case'start':selectProduct('cup');break;case'product':selectProduct(target.dataset.id);break;
 case'hero-single':case'hero-gift':state.heroGift=a==='hero-gift';render();announce(state.heroGift?'已换礼盒款：同一只杯子，增加礼盒和空白心意卡，示例价89元。':'已换按键款：杯身和杯盖，不含礼盒，示例价69元。');break;
 case'intro-audio':speak('欢迎来到淘明白。在这里，你可以先看商品怎么用，再比较规格差别，最后拆开清单看看会收到什么。点击喇叭可以听讲解，右上角可以调大文字。你可以慢慢选，这里不会自动下单。');break;
 case'filter':state.category=target.dataset.value;render();announce('已筛选'+state.category);break;case'clear-search':state.query='';state.category='全部';render();break;
 case'act':state.act=index;state.transcript='';stopSpeech();render();announce('已进入第'+(index+1)+'幕');break;case'previous-act':state.act=Math.max(0,state.act-1);render();break;case'next-act':state.act=Math.min(2,state.act+1);render();break;
 case'variant':case'choose-compare':selectVariant(index);break;case'color':state.colorIndex=index;state.checked=[false,false,false];render();announce('已选择'+color().name);break;
 case'demo':state.demoOpen=!state.demoOpen;render();announce(state.demoOpen?'演示已展开。'+variant().method:'演示已收起。');break;case'step':state.step=index;state.demoOpen=product().kind==='lamp'?index>0:product().kind==='box'?index<2:index===1;render();announce(variant().steps[index].title+'。'+variant().steps[index].detail);break;
 case'read-step':{const s=variant().steps[state.step];speak(s.title+'。'+s.detail);break;}case'read-selection':speak(spokenSummary(product(),variant(),color()));break;
 case'read-compare':{const p=product(),left=p.variants[state.compareA]||p.variants[0],right=p.variants[state.compareB]||p.variants[0];speak(`左边是${left.label}，${money(left.price).replace('¥','')}元。${left.method}。包含${left.includes.map(i=>i.name+' '+i.qty+'件').join('、')}。右边是${right.label}，${money(right.price).replace('¥','')}元。${right.method}。包含${right.includes.map(i=>i.name+' '+i.qty+'件').join('、')}。${p.source==='自己录入'?'以上信息由你录入，购买前请核对。':'以上是示例资料，不代表真实商品报价。'}`);break;}
 case'packing':state.act=2;state.exploded=true;render();announce('已摊开这一单。'+variant().includes.map(i=>`${i.name}${i.qty}件`).join('、')+'。不包含'+variant().excludes.join('、'));document.querySelector('.theater-panel').scrollIntoView({behavior:settings.motion?'instant':'smooth',block:'start'});break;
 case'unbox':state.exploded=!state.exploded;render();announce(state.exploded?'已展开。包含'+variant().includes.map(i=>`${i.name}${i.qty}件`).join('、')+'。不包含'+variant().excludes.join('、'):'已合上清单');break;
 case'add-cart':addToCart();break;case'quantity':{const i=state.cart[index];if(i){i.quantity=Math.min(99,Math.max(1,i.quantity+Number(target.dataset.delta)));persist();render();announce(i.name+'数量改为'+i.quantity);}break;}
 case'remove-item':{const removed=state.cart.splice(index,1)[0];state.removed={item:removed,index};persist();render();toast('已移除'+removed.name+'，可点击撤销移除。');break;}case'undo-remove':if(state.removed&&state.cart.length<20){const x=state.removed;if(state.cart.some(i=>i.key===x.item.key)){state.removed=null;render();toast('这件商品已重新加入清单，无需恢复。');break;}state.cart.splice(Math.min(x.index,state.cart.length),0,x.item);state.removed=null;persist();render();toast('已恢复到清单。');}break;
 case'settings':settingsDialog();break;case'help':helpDialog();break;case'close-modal':closeModal();break;
 case'setting-scale':settings.scale=Number(target.dataset.value);safeStorageSet('tm-settings',settings);render();settingsDialog();break;case'setting-rate':settings.rate=Number(target.dataset.value);safeStorageSet('tm-settings',settings);settingsDialog();break;
 case'reset-settings':Object.assign(settings,defaults);safeStorageSet('tm-settings',settings);render();settingsDialog();break;case'test-voice':closeModal();speak('这一次，我自己挑。你可以慢慢听，也可以随时停下来。');break;case'stop-speech':stopSpeech();toast('讲解已停止');break;
 case'edit-custom':editCustom();break;case'import':importDialog();break;case'import-example':document.getElementById('listing-text').value='桌面收纳盒\n规格：大号单只装\n价格：39元\n包含：盒体1只、盒盖1个\n不含：图片中的文具和贴纸\n尺寸：28×20×11厘米';break;
 case'remove-custom':openModal('删除这条商品资料？',`<p>只删除当前浏览器里的这条录入。已经保存到清单或分享出去的内容不受影响。</p><div class="dialog-actions">${btn('close-modal','保留','secondary')}${btn('confirm-remove-custom','删除录入','primary','','data-id="'+e(target.dataset.id)+'"')}</div>`);break;
 case'confirm-remove-custom':custom=custom.filter(p=>p.id!==target.dataset.id);safeStorageSet('tm-products',custom);closeModal();state.productId='cup';state.variantIndex=1;go('home');toast('已删除这条录入');break;
 case'seller-questions':await copyText(`您好，我想了解「${product().name}」的「${variant().label}」：\n${variant().unknowns.map((q,i)=>`${i+1}. ${q}，请问能提供具体信息吗？`).join('\n')}\n另外，请确认此规格实际包含：${variant().includes.map(i=>i.name+'×'+i.qty).join('、')}。`);break;
 case'read-cart':speak(listText(listPayload()));break;case'share':shareDialog();break;case'copy-share':await copyText(document.getElementById('share-url').value);break;case'preview-share':state.shared=listPayload();closeModal();go('shared');break;
 case'download':downloadText(listPayload());break;case'print':window.print();break;case'read-shared':if(state.shared)speak(listText(state.shared));break;case'download-shared':if(state.shared)downloadText(state.shared);break;
 case'about':openModal('把宝贝讲明白，把选择留给你',`<p>妈妈想给女儿挑一份生日礼物，却因为看不清详情，先把链接发给女儿帮忙。礼物还没买，惊喜已经说了出去。</p><p>淘明白希望把复杂商品说明变成可以听、看、选择的三幕小剧场，让更多人保留自主挑选的自在。</p><div class="notice neutral">这是淘宝创意作品的独立体验网站，非淘宝官方服务。当前内置商品为示例；可整理你自己录入的真实商品资料，但不读取淘宝账号、库存或订单，也不执行支付。</div><p>操作图形是原理与配置示意。真实商品效果、尺寸及价格应以商家资料为准。</p><div class="dialog-actions">${btn('close-modal','继续体验','primary')}</div>`);break;
 case'privacy':openModal('你的资料，留在你的浏览器里',`<ul class="how-to"><li><strong>保存在本机</strong>阅读偏好、录入商品和购物清单使用浏览器本地存储，不发送到我们的服务器。不建议在公用设备里保存个人资料。</li><li><strong>分享由你决定</strong>分享链接包含经过整理的清单与心意，持有链接的人可以读取。没有包含你的原商品粘贴全文、淘宝账号或地址。公开链接无法撤回，请谨慎填写。</li><li><strong>语音由设备提供</strong>本页不录音、不申请麦克风权限。朗读使用浏览器语音服务；具体处理方式取决于设备与语音引擎。</li><li><strong>这里不会自动下单</strong>返回淘宝原商品页由你主动点击，支付和订单由淘宝处理。</li></ul><div class="dialog-actions">${btn('clear-data','清除本机保存资料','secondary')}${btn('close-modal','知道了','primary')}</div>`);break;
 case'clear-data':openModal('清除本机保存的资料？',`<p>将移除当前浏览器里的商品、清单、备注和阅读偏好。已下载或已分享的内容不会被删除。</p><div class="dialog-actions">${btn('close-modal','先保留','secondary')}${btn('confirm-clear','确认清除','primary')}</div>`);break;
 case'confirm-clear':for(const key of ['tm-cart','tm-products','tm-note','tm-budget','tm-settings']){try{localStorage.removeItem(key)}catch{}}state.cart=[];state.removed=null;custom=[];state.note='';state.budget='';Object.assign(settings,defaults);closeModal();state.productId='cup';state.variantIndex=1;go('home');toast('本机保存的资料已清除');break;
 }});
document.addEventListener('input',event=>{const t=event.target;if(t.id==='product-search'&&!event.isComposing){state.query=t.value;render();}if(t.id==='cart-note'){state.note=t.value;safeStorageSet('tm-note',state.note);}if(t.id==='budget'){state.budget=t.value;safeStorageSet('tm-budget',state.budget);const el=document.getElementById('budget-status');const s=summarizeCart(state.cart);el.textContent=budgetText(s);el.classList.toggle('over',!!state.budget&&s.total>Number(state.budget));}});
document.addEventListener('compositionend',event=>{if(event.target.id==='product-search'){state.query=event.target.value;render();}});
document.addEventListener('change',event=>{const t=event.target;if(t.dataset.setting){settings[t.dataset.setting]=t.checked;safeStorageSet('tm-settings',settings);applySettings();}if(t.dataset.compare!==undefined){state[Number(t.dataset.compare)===0?'compareA':'compareB']=Number(t.value);render();announce('比较内容已更新');}if(t.id==='only-diff'){state.onlyDiff=t.checked;render();}if(t.dataset.check!==undefined){state.checked[Number(t.dataset.check)]=t.checked;announce(state.checked.every(Boolean)?'三项都核对好了，你可以放心地把这份选择记进清单。':'已记下你的核对。');}});
document.addEventListener('submit',event=>{if(event.target.id==='import-extract'){event.preventDefault();importReview(document.getElementById('listing-text').value);}if(event.target.id==='import-confirm'){event.preventDefault();saveImport(event.target);}});
document.addEventListener('keydown',event=>{if(event.altKey&&!event.ctrlKey&&!event.metaKey){if(['1','2','3'].includes(event.key)){event.preventDefault();if(modal.open)closeModal();go(['home','theater','cart'][Number(event.key)-1]);}if(event.key.toLowerCase()==='a'){event.preventDefault();settingsDialog();}}});
modal.addEventListener('cancel',()=>{stopSpeech();setTimeout(()=>{if(returnFocus?.isConnected)returnFocus.focus();else restoreFocus(returnFocusKey,true)},0);});
window.addEventListener('hashchange',()=>{if(location.hash.startsWith('#list=')){if(modal.open)closeModal();state.shared=decodeSharedList(location.hash);go('shared');}});
if(location.hash.startsWith('#list=')){state.shared=decodeSharedList(location.hash);state.view='shared';}
applySettings();render();
